// Munching XOR - two "munching squares" fronts (x XOR y < T), seam-free. Animated.
//
// The 1960s display hack: light every cell whose x XOR y is below a threshold
// that sweeps up and down; the lit region grows as nested squares/triangles.
// Two munchers run here, one on the diagonal and one on the anti-diagonal,
// each with a glowing front and a fading trail.
// SEAM-FREE: power-of-two grid with wrapped indices -> no jump at u = 0/1 or
// v = 0/1. Twisted gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = first muncher, u_col2 = background. The second
// muncher uses u_col1 with the channels rotated.

const int   BITS     = 7;      // 2^BITS cells per turn            [5 .. 9]
const float SPEED    = 0.25;   // sweep speed of the fronts
const float FRONT    = 0.06;   // width of the glowing front (fraction of the range)
const float TRAIL    = 0.30;   // brightness left behind the front  [0 .. 1]
const float GRID     = 0.25;   // faint XOR pattern on the background
const vec2  SHIFT     = vec2(0.3183, 0.2071); // moves the strongest lines of the
                                         // pattern off the seams (any value works)
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// brightness of a cell with value x for a front at threshold th (all in 0..1)
float muncher(float x, float th) {
    if (x > th) return 0.0;
    float behind = (th - x) / FRONT;
    return TRAIL + (1.0 - TRAIL) * exp(-behind);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 raw = fragCoord / iResolution.xy;
    vec2 uv = seamFold(raw) + SHIFT;

    int n = 1 << BITS;
    int m = n - 1;
    vec2 p = uv * float(n);
    ivec2 c = ivec2(floor(p)) & m;

    float x1 = float(c.x ^ c.y) / float(m);
    float x2 = float(c.x ^ (m - c.y)) / float(m);

    // thresholds sweep 0 -> 1 -> 0, the two fronts out of phase
    float th1 = 0.5 - 0.5 * cos(iTime * SPEED * TAU + 1.3);
    float th2 = 0.5 - 0.5 * cos(iTime * SPEED * TAU * 0.83 + 3.9);

    vec3 colA = u_col1;
    vec3 colB = u_col1.brg;
    vec3 col = u_col2 * (1.0 - GRID + GRID * (0.4 + 0.6 * x1 * x2));
    col += colA * muncher(x1, th1);
    col += colB * muncher(x2, th2);

    // thin dark lines between cells while they are big enough to show them
    vec2 fw = min(fwidth(raw), fwidth(fract(raw + 0.5))) * float(n);
    float px = max(fw.x, fw.y);
    vec2 f = fract(p);
    vec2 ed = min(f, 1.0 - f);
    float line = 1.0 - smoothstep(0.0, max(1.2 * px, 0.05), min(ed.x, ed.y));
    col *= 1.0 - 0.35 * line * (1.0 - smoothstep(0.2, 0.45, px));

    fragColor = vec4(min(col, vec3(1.2)), 1.0);
}
